begin;
create temp table content_checks(check_name text,passed boolean);
do $test$
declare admin_id uuid;ordinary uuid:=gen_random_uuid();ops uuid:=gen_random_uuid();doc jsonb;original jsonb;res jsonb;key text:='project:MTL-DA-001';v bigint;revision uuid;blocked boolean;members_before bigint;
begin
 select user_id into admin_id from private_website_lab.member_roles where role='full_admin' limit 1;
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select x,'content-rollback-'||x||'@example.invalid',now(),'{"full_name":"Content rollback fixture"}' from unnest(array[ordinary,ops])x;
 insert into private_website_lab.member_roles(user_id,role) values(ops,'operations_admin');
 perform set_config('request.jwt.claim.sub',ordinary::text,true);
 blocked:=false;begin perform public.website_content_admin('get',jsonb_build_object('key','page:home'));exception when insufficient_privilege then blocked:=true;end;assert blocked,'Ordinary member accessed draft';
 perform set_config('request.jwt.claim.sub',ops::text,true);
 blocked:=false;begin perform public.website_content_admin('list_pages',jsonb_build_object('key',key));exception when insufficient_privilege then blocked:=true;end;assert blocked,'Operations account bypassed website capability';
 doc:=public.website_content_admin('get',jsonb_build_object('key',key));assert doc->>'key'=key,'Operations project editor unavailable';
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 res:=public.website_content_admin('list_projects');assert jsonb_array_length(res->'rows')=25 and (res->>'page_size')::int=25,'Project pagination unbounded';
 assert not has_table_privilege('authenticated','private_website_content.documents','SELECT') and not has_table_privilege('anon','private_website_content.revisions','SELECT'),'Private drafts or revisions exposed';
 insert into content_checks values('Admin capabilities separate project editing from website publishing; direct draft access is denied and lists return 25 rows',true);
 doc:=public.website_content_admin('get',jsonb_build_object('key','page:home'));original:=doc->'published';v:=(doc->>'version')::bigint;
 perform public.website_content_admin('save',jsonb_build_object('key','page:home','expected_version',v,'data',jsonb_set(doc->'draft','{headline}','"ROLLBACK PRIVATE HEADLINE"')));
 assert public.website_content_public('page:home')->0->'data'=original,'Draft leaked into public response';
 blocked:=false;begin perform public.website_content_admin('save',jsonb_build_object('key','page:home','expected_version',v,'data',original));exception when serialization_failure then blocked:=true;end;assert blocked,'Stale writer overwrote newer draft';
 doc:=public.website_content_admin('get',jsonb_build_object('key','page:home'));v:=(doc->>'version')::bigint;
 blocked:=false;begin perform public.website_content_admin('publish',jsonb_build_object('key','page:home','expected_version',v,'confirmed',false,'note','Rollback publication'));exception when raise_exception then blocked:=true;end;assert blocked,'Publication accepted without confirmation';
 perform public.website_content_admin('publish',jsonb_build_object('key','page:home','expected_version',v,'confirmed',true,'note','Rollback homepage publication'));
 assert public.website_content_public('page:home')->0->'data'->>'headline'='ROLLBACK PRIVATE HEADLINE','Published content not read by public path';
 select id into revision from private_website_content.revisions where document_key='page:home' and version=1;
 doc:=public.website_content_admin('get',jsonb_build_object('key','page:home'));perform public.website_content_admin('restore',jsonb_build_object('key','page:home','expected_version',doc->'version','revision_id',revision));
 assert public.website_content_public('page:home')->0->'data'->>'headline'='ROLLBACK PRIVATE HEADLINE','Restore silently published';
 doc:=public.website_content_admin('get',jsonb_build_object('key','page:home'));assert doc->'draft'=original,'Starting version was not restorable';
 insert into content_checks values('Drafts stay private, stale saves are rejected, publish requires confirmation and initial content can be restored as a draft',true);
 doc:=public.website_content_admin('get',jsonb_build_object('key',key));original:=doc->'published';select count(*) into members_before from public.website_project_team_members;
 blocked:=false;begin perform public.website_content_admin('save',jsonb_build_object('key',key,'expected_version',doc->'version','data',jsonb_set(doc->'draft','{roles}','["Invented role"]')));exception when raise_exception then blocked:=true;end;assert blocked,'Brief editor changed protected roles';
 blocked:=false;begin perform public.website_content_admin('save',jsonb_build_object('key',key,'expected_version',doc->'version','data',jsonb_set(doc->'draft','{repository}','"javascript:alert(1)"')));exception when raise_exception then blocked:=true;end;assert blocked,'Unsafe repository accepted';
 perform public.website_content_admin('save',jsonb_build_object('key',key,'expected_version',doc->'version','data',jsonb_set(doc->'draft','{title}','"Rollback published project title"')));
 assert public.website_content_public(key)->0->'data'=original,'Project draft leaked';
 res:=public.website_content_admin('list_projects',jsonb_build_object('q','Rollback published project title'));assert (res->>'total')::integer=1 and jsonb_array_length(res->'rows')=1,'Draft-title search total differs from paginated rows';
 doc:=public.website_content_admin('get',jsonb_build_object('key',key));perform public.website_content_admin('publish',jsonb_build_object('key',key,'expected_version',doc->'version','confirmed',true,'note','Rollback project title publication'));
 assert (select title='Rollback published project title' from public.website_project_briefs where project_ref='MTL-DA-001'),'Operational title and public title diverged';
 assert (select count(*)=members_before from public.website_project_team_members),'Content editing altered membership';
 assert public.website_content_public(key)->0->'data'->'roles'=original->'roles','Public roles changed';
 insert into content_checks values('Project text publication updates the operational title while roles, memberships and permissions remain intact; unsafe URLs are rejected',true);
end $test$;
select * from content_checks;
rollback;
